INSERT [dbo].[essential_functions_original] ([id], [job_id], [function_text], [sort_order], [created_at], [updated_at]) VALUES (77, 22, N'The flex chaplain helps provide pastoral care and spiritual and emotional support to the patients, families and staff of Florida Hospital Waterman of all ages and backgrounds.
