INSERT [dbo].[essential_functions_original] ([id], [job_id], [function_text], [sort_order], [created_at], [updated_at]) VALUES (197, 61, N'The Lead Paramedic functions as one member of a crew assigned to an Emplify ambulance and will transport patients when necessary.  The Lead Paramedic is also responsible for (under the direction of the Supervisor and in cooperation with the Supervisor) rounding with on duty crews at outlying campuses and HBEDs, delivering supplies as necessary, assisting other crews with lifting and/or transporting patients, rounding with the staff at outlying Emergency Departments.  The Lead Paramedic may also inspect the Emplify ambulances that are in service for cleanliness and preparedness.', 1, CAST(N'2025-06-20T05:23:05.8733333' AS DateTime2), CAST(N'2025-06-20T05:23:05.8733333' AS DateTime2))
