INSERT [dbo].[essential_functions_original] ([id], [job_id], [function_text], [sort_order], [created_at], [updated_at]) VALUES (209, 73, N'Accurately reviews and codes up to 12 diagnosis and 12 procedures on inpatient charts per official inpatient coding guidelines.
Properly sequences diagnoses and procedures according to UHDDS definition and according to official coding guidelines.
Accurately codes outpatient ancillary tests per official outpatient coding guidelines.
