INSERT [dbo].[essential_functions_original] ([id], [job_id], [function_text], [sort_order], [created_at], [updated_at]) VALUES (227, 75, N'Manages designated day-to-day supply chain activities related to receiving, inventory management and distribution, implementing improvement plans as identified through observation and/or data
