INSERT [dbo].[essential_functions_original] ([id], [job_id], [function_text], [sort_order], [created_at], [updated_at]) VALUES (229, 77, N'Manage daily operations to assure effective and efficient provision of quality diagnostic procedures following the established protocols and industry standards.
