INSERT [dbo].[essential_functions_original] ([id], [job_id], [function_text], [sort_order], [created_at], [updated_at]) VALUES (231, 79, N'Performs all exams using established protocols. Uses facility policy for proper identification of patient prior to performing exam. Educates patient concerning exam. Properly screens patients for any contrast allergies
