INSERT [dbo].[essential_functions_original] ([id], [job_id], [function_text], [sort_order], [created_at], [updated_at]) VALUES (254, 97, N'Responsible for timely and accurate resolution of reconciling adjustments related to payment posting activities, including troubleshoot and resolve matching logic and provide resolution feedback to leadership
